import{_ as t}from"./chunks/emo.Cly4kUfc.js";import{_ as o,o as r,c as n,a5 as a}from"./chunks/framework.DGp912Ge.js";const h=JSON.parse('{"title":"Emergency Stop and Recovery Procedures","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/operation/emo.md","filePath":"manual/operation/emo.md","lastUpdated":1785806273000}'),s={name:"manual/operation/emo.md"};function i(c,e,p,l,d,u){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="emergency-stop-and-recovery-procedures" tabindex="-1">Emergency Stop and Recovery Procedures <a class="header-anchor" href="#emergency-stop-and-recovery-procedures" aria-label="Permalink to &quot;Emergency Stop and Recovery Procedures&quot;">​</a></h1><h2 id="emergency-stop-using-the-button" tabindex="-1">Emergency stop using the button <a class="header-anchor" href="#emergency-stop-using-the-button" aria-label="Permalink to &quot;Emergency stop using the button&quot;">​</a></h2><figure><img src="'+t+'" alt="Emergency stop button on rear of robot"><figcaption style="text-align:center;">[ Emergency stop push button on the rear of the robot ]</figcaption></figure><p>When the robot’s <strong>emergency stop button</strong> is pressed, all joints switch to <strong>High Damping</strong>. In this state, the robot’s legs resist external motion but <strong>do not</strong> accept torque or position commands. This is a safety mode to protect the user and the robot in an emergency or unintended motion.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>During emergency stop, control is disabled and the robot may lose posture and settle to the ground under gravity.</p></div></div><p>To recover from emergency stop:</p><ol><li>Rotate the emergency stop button clockwise and return it to its original position.</li><li>Press the &quot;Stance&quot; button in the GUI, or perform <a href="/RBQ/manual/operation/initial-pose.html">Robot Initial Pose Setting</a>.</li><li>Follow the initialization steps to return the robot to a ready state.</li></ol><p>This reinitializes joint control and robot posture correctly.</p>',8)])])}const b=o(s,[["render",i]]);export{h as __pageData,b as default};
